def parse_anchor(path):
    res = {}
    for line in open(path, encoding='utf-8', errors='replace'):
        c = cells(line)
        if not c or len(c) < 4:
            continue
        c0 = strip_md(c[0])
        if NID.match(c0):
            res[c0] = {'latest': strip_md(c[2]), 'result': strip_md(c[3]),
                       'method': strip_md(c[5]) if len(c) > 5 else '',
                       'conf': strip_md(c[-1])}
    return res

